import React from "react";
import { Container, Box, Grid, Paper, Typography, Button } from "@mui/material";

function LandingPage() {
  return (
    <Container maxWidth="lg" sx={{ mt: 8 }}>
      <Box sx={{ textAlign: "center", mb: 6 }}>
        <Typography variant="h2" sx={{ fontWeight: "bold", mb: 2 }}>
          Welcome to NOTESHARE
        </Typography>
        <Typography variant="h6" sx={{ mb: 3 }}>
          A secure platform for UL students to share and access study materials.
        </Typography>
        <Button variant="contained" color="primary" href="/register" sx={{ mr: 2 }}>
          Get Started
        </Button>
        <Button variant="outlined" color="primary" href="/login">
          Login
        </Button>
      </Box>

      <Grid container spacing={4} justifyContent="center">
        {[
          {
            title: "Verified Student Accounts",
            desc: "Only UL students with school emails can join, ensuring a trusted environment.",
          },
          {
            title: "Upload & Download Notes",
            desc: "Easily upload and download study guides, notes, and other learning resources.",
          },
          {
            title: "Search by Course Number",
            desc: "Quickly find study materials using course codes or class names.",
          },
          {
            title: "Ratings & Feedback",
            desc: "Rate and leave feedback to help others discover the most useful content.",
          },
          {
            title: "Class Groups",
            desc: "Join or create groups for your classes and get file recommendations.",
          },
        ].map((feature, index) => (
          <Grid item xs={12} sm={6} md={4} key={index}>
            <Paper elevation={3} sx={{ p: 3, height: "100%", textAlign: "center" }}>
              <Typography variant="h6" sx={{ fontWeight: "bold", mb: 1 }}>
                {feature.title}
              </Typography>
              <Typography variant="body1">{feature.desc}</Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>
    </Container>
  );
}

export default LandingPage;
